from fractions import Fraction as F
rates=[F(1,9),F(1,21)]; filled=F(0); t=F(0); i=0
while True:
    r=rates[i%2]
    if filled+r>=1:
        t+= (1-filled)/r; break
    filled+=r; t+=1; i+=1
opts={'A':10+F(3,7),'B':11+F(3,7),'C':9+F(3,7),'D':12+F(3,7)}
assert t==opts['D']
for k in 'ABC': assert t!=opts[k]
